CREATE TABLE product_batch(id BIGINT NOT NULL,sku_id BIGINT NOT NULL,batch_no VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,origin VARCHAR(200) NULL,proof_url VARCHAR(512) NULL,produced_on DATE NULL,expires_on DATE NULL,trace_description TEXT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_product_batch_sku_no(sku_id,batch_no),INDEX idx_product_batch_expiry(expires_on),CONSTRAINT fk_product_batch_sku FOREIGN KEY(sku_id) REFERENCES product_sku(id) ON DELETE CASCADE);
CREATE TABLE product_price_history(id BIGINT NOT NULL,sku_id BIGINT NOT NULL,old_price DECIMAL(18,2) NOT NULL,new_price DECIMAL(18,2) NOT NULL,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,changed_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_product_price_sku_time(sku_id,changed_at));
CREATE TABLE product_outbox(id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,aggregate_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,event_type VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,payload_json JSON NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'PENDING',retry_count INT UNSIGNED NOT NULL DEFAULT 0,next_retry_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),claimed_at DATETIME(6) NULL,published_at DATETIME(6) NULL,last_error VARCHAR(1000) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_product_outbox_dispatch(status,next_retry_at));
